import './theme.css';

import theme from '@seminar/theme-default';
import { createElement } from 'react';

import background from './background.svg';
import logo from './logo.svg';

/** The masters of the default theme, on a background. */
const master = Object.fromEntries(
  Object.entries(theme.master).map(([name, Master]) => [
    name,
    (props) =>
      createElement(
        'div',
        { style: { height: '100%', background: `url(${background})` } },
        createElement(Master, props),
      ),
  ]),
);

export default { ...theme, master };

export function Logo() {
  return createElement('img', { src: logo, alt: 'The logo' });
}
